#!/bin/bash
# usage: t.sh 'template'  -> prints  TPL<TAB>OUT<TAB>EXIT  with err extracted
cd /workspace
while IFS= read -r line; do
  [ -z "$line" ] && continue
  out=$(./executable -i "$line" 2>/tmp/err.txt); rc=$?
  err=$(python3 -c '
import json,sys
s=open("/tmp/err.txt").read().strip()
if not s: print("")
else:
  parts=[]
  for l in s.splitlines():
    try: parts.append(json.loads(l).get("err",l))
    except Exception: parts.append(l)
  print(" || ".join(parts))
')
  printf '%s\t[%s]\trc=%s\tERR=%s\n' "$line" "$out" "$rc" "$err"
done

