#!/usr/bin/env python3
import json, subprocess, sys, os
os.chdir("/workspace")
data = sys.stdin.read().split("\n")
for tpl in data:
    if tpl.strip() == "":
        continue
    p = subprocess.run(["./executable", "-i", tpl], capture_output=True, text=True)
    errs = []
    for l in p.stderr.strip().splitlines():
        try:
            errs.append(json.loads(l).get("err", l))
        except Exception:
            errs.append(l)
    print("TPL: " + tpl)
    print("OUT: " + repr(p.stdout))
    print("RC : %d" % p.returncode)
    if errs:
        print("ERR: " + " ||| ".join(errs))
    print("---")

